import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
@synth.generator
def patch_pairs(ctx):
    inputs = torch.randn(4, generator=ctx.rng.torch)
    keys = torch.randn(3, 2, generator=ctx.rng.torch)
    return {"inputs": synth.Tensor(inputs), "keys": synth.Tensor(keys)}
dataset = synth.Spec("cut-patchnce-pairs", generator=patch_pairs, size=8, splits={"train": 1.0}, seed=7, root=root, monitor="none").run()
train = dataset.for_recipe("structured-objective", split="train")
class PatchQuery(nn.Module):
    def __init__(self):
        super().__init__()
        self.network = build("mlp", "tiny", in_features=4, out_features=6)
    def forward(self, inputs):
        return {"queries": self.network(inputs).reshape(-1, 3, 2)}
trainer = Trainer(PatchQuery(), train, recipe="structured-objective", recipe_config={"loss": "cut-patchnce", "loss_kwargs": {"temperature": 0.07}, "bindings": {"logits_or_prediction": {"output": "queries"}, "targets": {"batch": "keys"}}}, batch_size=4, max_epochs=1, device="cpu")
trainer.fit()
